// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(options.BaseURL+"/system/health", wrapper.GetSystemHealth, options.OperationMiddlewares["GetSystemHealth"]...)
	router.GET(options.BaseURL+"/system/discover", wrapper.GetSystemDiscover, options.OperationMiddlewares["GetSystemDiscover"]...)
	router.GET(options.BaseURL+"/system/bootstrap", wrapper.GetSystemBootstrap, options.OperationMiddlewares["GetSystemBootstrap"]...)
	router.POST(options.BaseURL+"/sandbox", wrapper.PostSandbox, options.OperationMiddlewares["PostSandbox"]...)
	router.GET(options.BaseURL+"/dashboard", wrapper.GetDashboard, options.OperationMiddlewares["GetDashboard"]...)
	router.POST(options.BaseURL+"/decisions", wrapper.ProposeDecision, options.OperationMiddlewares["proposeDecision"]...)
	router.GET(options.BaseURL+"/decisions/:id/lineage", wrapper.GetDecisionsIdLineage, options.OperationMiddlewares["GetDecisionsIdLineage"]...)
	router.POST(options.BaseURL+"/agents/handoff", wrapper.ExecuteHandoff, options.OperationMiddlewares["executeHandoff"]...)
	router.POST(options.BaseURL+"/agents/resume", wrapper.PostAgentsResume, options.OperationMiddlewares["PostAgentsResume"]...)
	router.GET(options.BaseURL+"/audit/verify", wrapper.GetAuditVerify, options.OperationMiddlewares["GetAuditVerify"]...)
	router.GET(options.BaseURL+"/audit/export", wrapper.GetAuditExport, options.OperationMiddlewares["GetAuditExport"]...)
	router.GET(options.BaseURL+"/budget", wrapper.GetBudget, options.OperationMiddlewares["GetBudget"]...)
	router.POST(options.BaseURL+"/budget/consume", wrapper.PostBudgetConsume, options.OperationMiddlewares["PostBudgetConsume"]...)
	router.POST(options.BaseURL+"/router/evaluate", wrapper.PostRouterEvaluate, options.OperationMiddlewares["PostRouterEvaluate"]...)
	router.GET(options.BaseURL+"/debug/token", wrapper.GetDebugToken, options.OperationMiddlewares["GetDebugToken"]...)

}
